public class StringPoolDemonstration {
    public static void main(String[] args) {
        // Literal creation: Allocated in the String Constant Pool
        String s1 = "EnterpriseJava";
        String s2 = "EnterpriseJava";

        // Evaluates to true because both reference the exact same pooled instance
        System.out.println(s1 == s2);

        // Heap allocation: Creates a new object on the heap, bypassing literal pooling
        String s3 = new String("EnterpriseJava");

        // Evaluates to false because s3 points to a distinct heap object
        System.out.println(s1 == s3);

        // Explicit interning: Forces s3's value into the SCP and returns the pooled reference
        String s4 = s3.intern();

        // Evaluates to true because s4 now points to the canonical instance in the SCP
        System.out.println(s1 == s4);
    }
}
